<?php require_once __DIR__."/../config/database.php";require_once __DIR__."/../includes/functions.php";requireLogin();$fp=(int)($_GET["prodi_id"]??0);$fs=$_GET["status"]??"";$q=trim($_GET["q"]??"");$w=["1=1"];$p=[];if($fp){$w[]="s.prodi_id=?";$p[]=$fp;}if($fs){$w[]="s.status=?";$p[]=$fs;}if($q){$w[]="(s.nomor_surat LIKE ? OR s.nama_penerima LIKE ?)";$p[]="%$q%";$p[]="%$q%";}$ws=implode(" AND ",$w);$data=dbQuery("SELECT s.nomor_surat,s.jenis_surat,s.nama_penerima,s.nim_nidn,p.nama,s.perihal,s.tanggal,s.status FROM surat s JOIN prodi p ON p.id=s.prodi_id WHERE $ws ORDER BY s.created_at DESC",$p);header("Content-Type: text/csv; charset=UTF-8");header("Content-Disposition: attachment; filename=\"surat_".date("Ymd").".csv\"");$f=fopen("php://output","w");fputs($f,"\xEF\xBB\xBF");fputcsv($f,["Nomor Surat","Jenis","Penerima","NIM/NIDN","Prodi","Perihal","Tanggal","Status"]);foreach($data as $r)fputcsv($f,array_values($r));fclose($f);exit;
